/* ------------------------------------------------------------------ public API (in-process) */

/** What other modules may call in-process: `ctx.use('access')` (or `ctx.tryUse` for an optional dependency). */
export interface AccessPublicApi {
  /** Kernel guard for every admin endpoint with a `permission`. Includes roles covered as a backup only where the away period grants them. Used by: kernel. */
  hasPermission(principal: identity.Principal, permissionKey: string): Promise<boolean>;
  /** Effective staff permissions (cached, invalidated on access.role.changed) Used by: kernel, reports. */
  permissionsOf(accountId: string): Promise<string[]>;
  /** allowed | approval_required | denied for this person, action and amount, with who could approve. Uses the limits in force now. Permissions alone never make a money action allowed. Used by: finance, returns, payments, sellers, offers, catalog, inventory, purchasing, shipping, support, promotions, customers, settings, content, advertising, audit, wallet. */
  check(principal: identity.Principal, action: string, amount?: AmountInput): Promise<AuthorityCheck>;
  /** Create an approval request (or return the open one for the same action and target). The requesting module keeps its record pending and finishes on access.approval.decided. Used by: finance, returns, sellers, offers, catalog, inventory, purchasing, shipping, support, promotions, customers, settings, content, advertising, audit, wallet. */
  requestApproval(input: RequestApprovalInput): Promise<ApprovalRequest>;
  /** Same rules as the admin approve/reject/return endpoints, for modules that show the decision inside their own screen (payout run approval). An approval above stepUpAbove needs reauthToken: a re-auth token for purpose approval issued to this principal's session (used once; given back when the decision fails) Used by: finance, returns, sellers. */
  decide(requestId: string, principal: identity.Principal, decision: { kind: 'approve' | 'reject' | 'return', note?: string, reauthToken?: string }): Promise<ApprovalRequest>;
  /** The requesting module withdraws a request (record changed or deleted) Used by: finance, returns, sellers, offers, settings. */
  cancelApproval(requestId: string, by: common.Actor, reason: string): Promise<void>;
  /** Full request with decisions Used by: audit, finance, returns, sellers. */
  getApproval(requestId: string): Promise<ApprovalRequest | null>;
  /** Compact common.ApprovalInfo for embedding in other modules' responses Used by: finance, returns, sellers, offers, inventory, purchasing, settings, content, promotions. */
  approvalInfo(requestId: string): Promise<common.ApprovalInfo>;
  /** Who receives a role's work and notices right now: lead, or the covering backup while the lead is away (the lead keeps a copy) Used by: notifications, workqueues, support. */
  resolveRecipients(roleKey: string): Promise<RecipientResolution>;
  /** Active roles of a staff member (audit stores them with each entry; advertising takes a reviewer's role from here, never from the request body) Used by: audit, notifications, workqueues, advertising. */
  rolesOf(accountId: string): Promise<RoleRef[]>;
  /** Whether a staff member may disable an account: a Business Owner only by another Business Owner (code FORBIDDEN), never the last active one (LAST_BUSINESS_OWNER). Identity asks before disabling, because disabling ends every role Used by: identity. */
  disableCheck(accountId: string, byAccountId: string | null): Promise<{ allowed: boolean, code: string | null, reason: string | null }>;
  /** Everyone holding a role (assignment pickers in workqueues and support) Used by: workqueues, support, notifications. */
  membersOfRole(roleKey: string): Promise<StaffRef[]>;
  /** Active staff members whose active role assignments grant the permission (same rule as hasPermission; disabled accounts left out, locked ones shown away). includeCovering adds people who hold it only as an away-period backup. For handler pickers and routing to whoever can act (support case handlers, notifications). Used by: support, workqueues, notifications, messaging. */
  staffWithPermission(permissionKey: string, opts?: { includeCovering?: boolean }): Promise<StaffRef[]>;
  /** Requests the caller may decide now, oldest due first (same rules as GET /approval-requests?view=to_decide). canDecide and steps are computed for the caller. Used by: graphql. */
  listApprovalsToDecide(principal: identity.Principal, filter: { module?: string, actionKey?: string, overdue?: boolean }, page: common.PageInput): Promise<common.Page<ApprovalRequest>>;
  /** Approval counts for the admin dashboard and inbox Used by: graphql. */
  approvalSummaryFor(principal: identity.Principal): Promise<{ toDecide: number, overdue: number, dueSoon: number, myOpenRequests: number, returnedToMe: number }>;
  /** One request with decisions and steps, null unless the caller is the requester, an eligible approver or holds access.approvals.view-all. canDecide and cannotDecideReason are for the caller. Used by: graphql. */
  getApprovalForViewer(principal: identity.Principal, requestId: string): Promise<ApprovalRequest | null>;
  /** Batched: the current approval request per target record (open request first, else the latest decided one), for approval panels embedded in other modules' admin views (payout run, hold, refund request). Visibility follows the parent record; canDecide is for the caller. Used by: graphql. */
  approvalForTargets(principal: identity.Principal, targetType: string, targetIds: string[]): Promise<Map<string, ApprovalRequest | null>>;
  /** Batched: open requests whose target belongs to each seller (ApprovalTarget.sellerId), for the admin seller 360 Used by: graphql. */
  approvalsForSellers(principal: identity.Principal, sellerIds: string[]): Promise<Map<string, ApprovalRequest[]>>;
  /** Leads, backups and who receives each role's work today (GET /coverage without gaps), for the admin dashboard Used by: graphql. */
  coverageNow(filter: { workArea?: string }): Promise<RoleCoverage[]>;
  /** The caller's own authority, limit, second-review rule and approval route for one action (decision panels) Used by: graphql. */
  myLimitFor(principal: identity.Principal, actionKey: string): Promise<MyActionLimit>;
  /** A staff member's display name and role label (roleLabel) for assignee, owner, reviewer and decider columns Used by: support, finance, trust, workqueues, reports. */
  getStaffRef(staffId: string): Promise<StaffRef | null>;
}

