  events: {
    publishes: {
      "access.approval.requested": { when: "An approval request is created or resubmitted", payload: () => AccessApprovalRequestedEvent },
      "access.approval.partially_approved": { when: "A first approval is recorded and another is still needed", payload: () => AccessApprovalPartiallyApprovedEvent },
      "access.approval.returned": { when: "A reviewer sends a request back with a comment", payload: () => AccessApprovalReturnedEvent },
      "access.approval.decided": { when: "A request reaches a final outcome", payload: () => AccessApprovalDecidedEvent },
      "access.approval.reminder_sent": { when: "Someone reminds the eligible reviewers, or the reminder job runs", payload: () => AccessApprovalReminderSentEvent },
      "access.role.changed": { when: "A role is created, edited, archived, its permissions change, or it is assigned or removed", payload: () => AccessRoleChangedEvent },
      "access.limits.changed": { when: "An approved limit change takes effect", payload: () => AccessLimitsChangedEvent },
      "access.coverage.changed": { when: "Who receives a role's work changes (lead/backups edited, away period starts or ends, assignment removed)", payload: () => AccessCoverageChangedEvent },
      "access.away.started": { when: "An away period begins", payload: () => AccessAwayStartedEvent },
      "access.away.ended": { when: "An away period ends (on time or early)", payload: () => AccessAwayEndedEvent },
    },
    consumes: {
      "identity.invitation.accepted": "Activate pending_acceptance role assignments of a newly accepted staff member (including sensitive grants already approved); assignments still pending_approval wait for their approval and then become active",
      "identity.invitation.revoked": "End the role assignments still waiting for the revoked staff invitation (pending_acceptance revoked, pending_approval rejected and its approval request cancelled), so the roles can be granted again, e.g. a new Business Owner bootstrap",
      "identity.account.disabled": "Revoke all role assignments, remove the person as lead/backup, drop them from eligible approvers of open requests, and publish access.coverage.changed with the gap",
      "identity.account.locked": "Treat a locked staff member as unavailable for routing (backup receives) until unlocked",
      "identity.account.unlocked": "Restore routing to the unlocked staff member"
    },
  },
  jobs: {
    "access.sync-registry": {
      "schedule": "on boot",
      "does": "Upsert permissions and approval actions from enabled module manifests; mark those of disabled modules unavailable (kept for history); seed the system roles on first boot"
    },
    "access.apply-limit-changes": {
      "schedule": "every minute",
      "does": "Apply scheduled limit changes whose effectiveFrom has passed; publish access.limits.changed"
    },
    "access.run-away-periods": {
      "schedule": "every 5 min",
      "does": "Start scheduled away periods and end active ones at their time; publish access.away.started/ended and access.coverage.changed"
    },
    "access.expire-approval-requests": {
      "schedule": "every 15 min",
      "does": "Expire open requests past expires_at (dueAt + grace, or approvalRequestTtlHours) and publish access.approval.decided with outcome expired"
    },
    "access.remind-approvals": {
      "schedule": "every 30 min",
      "does": "Remind eligible reviewers of requests due within reminderHoursBeforeDue or waiting longer than reminderAfterHours; escalate to the role's escalation role when overdue"
    },
    "access.expire-assignments": {
      "schedule": "hourly",
      "does": "Expire role assignments past expiresAt (temporary access)"
    }
  },
  settings: {
    "approvalRequestTtlHours": {
      "default": 72,
      "desc": "Open requests without a due date expire after this",
      "type": "duration",
      "min": 1,
      "unit": "hours",
      "approval": "second_reviewer"
    },
    "reminderHoursBeforeDue": {
      "default": 4,
      "desc": "Remind reviewers this long before dueAt",
      "type": "duration",
      "min": 0,
      "unit": "hours"
    },
    "reminderAfterHours": {
      "default": 24,
      "desc": "Remind reviewers of undated requests waiting this long",
      "type": "duration",
      "min": 1,
      "unit": "hours"
    },
    "reminderMinIntervalMinutes": {
      "default": 60,
      "desc": "Manual reminders per request",
      "type": "duration",
      "min": 1,
      "unit": "minutes"
    },
    "stepUpAbove": {
      "default": {
        "amount": 1000000,
        "currency": "USD"
      },
      "desc": "Money approvals above this need the approver's password again (a re-auth token, purpose approval)",
      "type": "money",
      "min": 0,
      "approval": "business_owner"
    },
    "sensitivePermissionPrefixes": {
      "default": [
        "access.",
        "identity.staff-accounts.",
        "finance.",
        "audit.entries.export",
        "settings.changes."
      ],
      "desc": "Granting these needs a second reviewer",
      "type": "json",
      "approval": "business_owner"
    }
  },
  errorCodes: {
    "SELF_APPROVAL_NOT_ALLOWED": {
      "status": 403,
      "meaning": "You cannot approve or reject your own request."
    },
    "NOT_ELIGIBLE_APPROVER": {
      "status": 403,
      "meaning": "Your roles' limits do not cover this action or amount. details.eligibleRoles lists who can."
    },
    "ALREADY_APPROVED_BY_YOU": {
      "status": 409,
      "meaning": "The second approval must come from a different person."
    },
    "SYSTEM_ROLE": {
      "status": 409,
      "meaning": "Seeded roles cannot be archived or have their key changed."
    },
    "ROLE_IN_USE": {
      "status": 409,
      "meaning": "Remove the role from all staff before archiving it."
    },
    "LAST_BUSINESS_OWNER": {
      "status": 409,
      "meaning": "At least one active Business Owner must remain."
    },
    "COVERAGE_INVALID": {
      "status": 400,
      "meaning": "Lead and backups must hold the role, a backup cannot be the lead, and every led role needs cover. details.issues."
    },
    "AWAY_OVERLAP": {
      "status": 409,
      "meaning": "This person already has an away period in that time."
    },
    "UNKNOWN_PERMISSION": {
      "status": 400,
      "meaning": "details.keys are not in the permission registry (or their module is disabled)."
    },
    "UNKNOWN_APPROVAL_ACTION": {
      "status": 400,
      "meaning": "The action key is not registered by any enabled module."
    },
    "REMINDER_TOO_SOON": {
      "status": 429,
      "meaning": "Reviewers were reminded recently; try again after details.nextAllowedAt."
    }
  },
